package spec

import (
	"bytes"
	"fmt"
	"go/format"
	"sort"
)

// Header is the first line of every generated file.
const Header = "// Code generated by fldlint; DO NOT EDIT."

// Generate renders rules_gen.go content for rf, deterministically and gofmt-clean.
func Generate(rf *RulesFile) ([]byte, error) {
	var b bytes.Buffer
	b.WriteString(Header + "\n\npackage spec\n\n")

	b.WriteString("var genSkipCategories = map[string]SkipCategory{\n")
	for _, k := range rf.SkipCategoryNames() {
		c := rf.SkipCategories[k]
		fmt.Fprintf(&b, "\t%q: {Severity: %q, Message: %q},\n", k, c.Severity, c.Message)
	}
	b.WriteString("}\n\n")

	b.WriteString("var genRules = []Rule{\n")
	index := map[string]int{}
	for i, r := range rf.Rules {
		fmt.Fprintf(&b, "\t{\n\t\tID: %q, ValueType: %q, Risk: %q,\n", r.ID, r.ValueType, r.Risk)
		fmt.Fprintf(&b, "\t\tKeyArg: %d, DefaultArg: %d, ContextArg: %d,\n", r.KeyArg, r.DefaultArg, r.ContextArg)
		fmt.Fprintf(&b, "\t\tSkip: %q, Message: %q,\n", r.Skip, r.Message)
		if g := r.Go; g != nil {
			b.WriteString("\t\tGo: &GoBinding{\n")
			fmt.Fprintf(&b, "\t\t\tMethods: %s,\n", strSlice(g.Methods))
			if len(g.CtxArg) > 0 {
				keys := make([]string, 0, len(g.CtxArg))
				for k := range g.CtxArg {
					keys = append(keys, k)
				}
				sort.Strings(keys)
				b.WriteString("\t\t\tCtxArg: map[string]int{")
				for j, k := range keys {
					if j > 0 {
						b.WriteString(", ")
					}
					fmt.Fprintf(&b, "%q: %d", k, g.CtxArg[k])
				}
				b.WriteString("},\n")
			}
			fmt.Fprintf(&b, "\t\t\tTemplate: %q,\n", g.Template)
			if len(g.Requires) > 0 {
				fmt.Fprintf(&b, "\t\t\tRequires: %s,\n", strSlice(g.Requires))
			}
			b.WriteString("\t\t},\n")
			for _, m := range g.Methods {
				index[m] = i
			}
		}
		b.WriteString("\t},\n")
	}
	b.WriteString("}\n\n")

	b.WriteString("var genGoIndex = map[string]int{\n")
	names := make([]string, 0, len(index))
	for m := range index {
		names = append(names, m)
	}
	sort.Strings(names)
	for _, m := range names {
		fmt.Fprintf(&b, "\t%q: %d,\n", m, index[m])
	}
	b.WriteString("}\n")

	out, err := format.Source(b.Bytes())
	if err != nil {
		return nil, fmt.Errorf("format generated source: %w", err)
	}
	return out, nil
}

func strSlice(s []string) string {
	var b bytes.Buffer
	b.WriteString("[]string{")
	for i, v := range s {
		if i > 0 {
			b.WriteString(", ")
		}
		fmt.Fprintf(&b, "%q", v)
	}
	b.WriteString("}")
	return b.String()
}
